<?php
namespace App\Notifications;
use App\Models\PayrollRun; use Illuminate\Bus\Queueable; use Illuminate\Contracts\Queue\ShouldQueue; use Illuminate\Notifications\Messages\MailMessage; use Illuminate\Notifications\Notification;
class PayrollApprovedNotification extends Notification implements ShouldQueue { use Queueable; public function __construct(public int $runId,public int $month,public int $year,public string $netSalary){} public static function fromRun(PayrollRun $run,string $net):self{return new self($run->id,$run->month,$run->year,$net);} public function via(object $notifiable):array{return filled($notifiable->email)?['database','mail']:['database'];} public function toArray(object $notifiable):array{return ['kind'=>'payroll_approved','run_id'=>$this->runId,'month'=>$this->month,'year'=>$this->year,'net_salary'=>$this->netSalary,'message'=>"Payroll {$this->month}/{$this->year} was approved."]; } public function toMail(object $notifiable):MailMessage{return (new MailMessage)->subject('Payra payroll approved')->line("Your payroll for {$this->month}/{$this->year} has been approved.")->line("Net salary: {$this->netSalary} JOD")->action('Open Payra',url('/self-service'));} }
